def apply_cross_domain_depth_v160(deep_modules):
    """Apply known-title in-place enrichments without risking a boot failure.

    Returns a small report so audits can verify what matched. An unmatched title
    is intentionally reported rather than used as a reason to take down the app.
    """
    applied = []
    missing = []
    for domain, patches in PATCHES_V160.items():
        modules = deep_modules.get(domain, [])
        for patch in patches:
            found = None
            for module in modules:
                if module.get("topic") in patch["candidates"]:
                    found = module
                    break
            if found is None:
                missing.append((domain, patch["candidates"]))
                continue
            found.update(patch["fields"])
            applied.append((domain, found.get("topic")))
    return {"applied": applied, "missing": missing}
